    /// </summary>
    /// <remarks>
    /// Su última versión.
    /// <br/>
    /// <c>GET /v1/quotes/{id}</c>
    /// <br/>
    /// <see href="https://fiscalisto.com/docs/api/referencia/cotizaciones/get-quote"/>
