    /// <br/>
    /// <c>GET /v1/quotes/{id}/pdf</c>
    /// <br/>
    /// <see href="https://fiscalisto.com/docs/api/referencia/cotizaciones/get-quote-pdf"/>
    /// </remarks>
    /// <exception cref="FiscalistoException">La API contestó con un error o no contestó.</exception>
